using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Threading;
using System.Threading.Tasks;
using System.Windows;
using System.Windows.Controls;
namespace FrameScout {
 public class CalibrationSample {public string Path,Name,Fingerprint,Kind;public int Frame;public double Time;public bool IsError;public string Label {get {return IsError?"确认异常":"确认正常";}}}
 public sealed partial class Shell {
  readonly List<CalibrationSample> samples=new List<CalibrationSample>();
  string CalibrationPath {get {return Path.Combine(Path.GetDirectoryName(Settings.FilePath),"calibration.json");}}
  void MoveVideo(int delta) {var order=videos.Items.Cast<VideoItem>().ToList();if(order.Count==0)return;int at=order.IndexOf(current);int next=Math.Max(0,Math.Min(order.Count-1,at+delta));videos.SelectedItem=order[next];videos.ScrollIntoView(order[next]);QueueSave();}
  void AddCalibrationSample(VideoItem item,int frame,string kind,bool error) {try {if(samples.Count==0&&File.Exists(CalibrationPath))samples.AddRange(Util.Json().Deserialize<List<CalibrationSample>>(File.ReadAllText(CalibrationPath))??new List<CalibrationSample>());double time=item.Result!=null&&frame<item.Result.Times.Count?item.Result.Times[frame]:frame/item.Info.Fps;var existing=samples.FirstOrDefault(x=>x.Path==item.Path&&x.Frame==frame&&x.Kind==kind);if(existing!=null){existing.IsError=error;existing.Fingerprint=Fingerprint(item.Path);existing.Time=time;}else samples.Add(new CalibrationSample {Path=item.Path,Name=item.Name,Fingerprint=Fingerprint(item.Path),Frame=frame,Time=time,Kind=kind,IsError=error});Directory.CreateDirectory(Path.GetDirectoryName(CalibrationPath));File.WriteAllText(CalibrationPath,Util.Json().Serialize(samples));statusText.Text="已保存校准样本："+kind+" · "+(error?"确认异常":"确认正常");}catch(Exception ex){statusText.Text="样本保存失败："+ex.Message;}}
  void OpenCalibration() {if(samples.Count==0&&File.Exists(CalibrationPath))try{samples.AddRange(Util.Json().Deserialize<List<CalibrationSample>>(File.ReadAllText(CalibrationPath))??new List<CalibrationSample>());}catch {}var w=FrameWindows.Dialog(Window,"实际素材样本校准",900,620);var grid=new Grid {Margin=new Thickness(14)};grid.RowDefinitions.Add(new RowDefinition {Height=GridLength.Auto});grid.RowDefinitions.Add(new RowDefinition());grid.RowDefinitions.Add(new RowDefinition {Height=GridLength.Auto});var hint=new TextBlock {Text="先在“连续帧对照”中保存你确认的正常 / 异常样本，再比较 0、15、30、50、75、100 六档。标注越有代表性，建议越可信。",TextWrapping=TextWrapping.Wrap,Margin=new Thickness(0,0,0,10)};grid.Children.Add(hint);var table=new DataGrid {ItemsSource=samples.ToList(),AutoGenerateColumns=false,IsReadOnly=true};table.Columns.Add(new DataGridTextColumn {Header="视频",Binding=new System.Windows.Data.Binding("Name"),Width=210});table.Columns.Add(new DataGridTextColumn {Header="类别",Binding=new System.Windows.Data.Binding("Kind"),Width=80});table.Columns.Add(new DataGridTextColumn {Header="时间（秒）",Binding=new System.Windows.Data.Binding("Time"),Width=100});table.Columns.Add(new DataGridTextColumn {Header="标注",Binding=new System.Windows.Data.Binding("Label"),Width=110});Grid.SetRow(table,1);grid.Children.Add(table);var tools=new WrapPanel {Margin=new Thickness(0,12,0,0)};var start=new Button {Content="开始校准"};var cancelButton=new Button {Content="停止",IsEnabled=false};var apply=new Button {Content="采用推荐值",IsEnabled=false};tools.Children.Add(start);tools.Children.Add(cancelButton);tools.Children.Add(apply);Grid.SetRow(tools,2);grid.Children.Add(tools);w.Content=grid;CancellationTokenSource cancel=null;int recommendation=-1;cancelButton.Click+=(s,e)=> {if(cancel!=null)cancel.Cancel();};w.Closed+=(s,e)=> {if(cancel!=null)cancel.Cancel();};apply.Click+=(s,e)=> {if(recommendation>=0){sensitivity.Value=recommendation;QueueSave();hint.Text="已设置灵敏度 "+recommendation+"；新参数在重新检测时生效。";}};
   start.Click+=async(s,e)=> {if(scanCancel!=null){hint.Text="请先停止视频检测，再校准。";return;}var valid=new List<CalibrationSample>();foreach(var sample in samples)try{if(File.Exists(sample.Path)&&Fingerprint(sample.Path)==sample.Fingerprint)if(sample.Kind=="夹帧"||sample.Kind=="黑屏")valid.Add(sample);}catch {}if(!valid.Any(x=>x.IsError)||!valid.Any(x=>!x.IsError)){hint.Text="至少需要一条确认异常与一条确认正常的样本；文件变化后的旧样本不会使用。";return;}start.IsEnabled=false;cancelButton.IsEnabled=true;apply.IsEnabled=false;cancel=new CancellationTokenSource();var ct=cancel.Token;var results=new List<CalibrationScore>();try {int[] values={0,15,30,50,75,100};foreach(int value in values){ct.ThrowIfCancellationRequested();hint.Text="正在比较灵敏度 "+value+"，每个唯一视频分析一次，可随时停止。";var options=ReadSettings();options.SensitivityValue=value;var cache=new Dictionary<string,AnalysisResult>();foreach(var file in valid.Select(x=>x.Path).Distinct()){ct.ThrowIfCancellationRequested();cache[file]=await Task.Run(()=>Detector.Analyze(file,options,null,ct));}int tp=0,fp=0,miss=0;foreach(var label in valid){bool found=cache[label.Path].Findings.Any(f=>f.Kind==label.Kind&&label.Frame>=f.Frame-1&&label.Frame<=f.EndFrame+1);if(found&&label.IsError)tp++;else if(found&&!label.IsError)fp++;else if(!found&&label.IsError)miss++;}results.Add(new CalibrationScore {Sensitivity=value,TruePositives=tp,FalsePositives=fp,Misses=miss,Penalty=fp*2+miss});}var best=results.OrderBy(x=>x.Penalty).ThenBy(x=>x.Sensitivity).First();recommendation=best.TruePositives>0?best.Sensitivity:-1;hint.Text=recommendation<0?"各档都未命中异常样本，暂不能推荐；请检查持续帧数、黑屏范围或补充样本。":"推荐 "+recommendation+"（误报权重为漏报的两倍）。这是当前标注样本的建议，请继续加入实际素材验证。";table.AutoGenerateColumns=false;table.Columns.Clear();foreach(var spec in new[]{new[]{"灵敏度","Sensitivity"},new[]{"命中异常","TruePositives"},new[]{"误报","FalsePositives"},new[]{"漏报","Misses"},new[]{"综合扣分","Penalty"}})table.Columns.Add(new DataGridTextColumn {Header=spec[0],Binding=new System.Windows.Data.Binding(spec[1]),Width=110});table.ItemsSource=results;apply.IsEnabled=recommendation>=0;}catch(OperationCanceledException){hint.Text="校准已停止。";}catch(Exception ex){hint.Text="校准失败："+ex.Message;}finally{start.IsEnabled=true;cancelButton.IsEnabled=false;cancel.Dispose();cancel=null;}};w.Show();
  }
 }
 public class CalibrationScore {public int Sensitivity {get;set;}public int TruePositives {get;set;}public int FalsePositives {get;set;}public int Misses {get;set;}public int Penalty {get;set;}}
}
